import{_ as i,o as n,c as h,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-7-create-user/report3_spec.md","filePath":"feature/admin-management/3-10-7-create-user/report3_spec.md"}'),l={name:"feature/admin-management/3-10-7-create-user/report3_spec.md"};function r(g,t,a,e,s,u){return n(),h("div",null,[...t[0]||(t[0]=[o("<p><strong>3.10.7 Create User (Tạo Người Dùng Mới)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) nhấn nút &quot;+ Tạo người dùng mới&quot; tại trang /admin/users.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên tạo tài khoản người dùng mới trực tiếp từ trang quản trị.</li><li><strong>Purpose</strong>: Tạo tài khoản ADMIN/USER phải xác thực email và thay mật khẩu ban đầu trước khi sử dụng bình thường.</li><li><strong>Interface</strong>: Hộp thoại Tạo Người Dùng (SCR-ADM-07), gồm hồ sơ, system role, gói catalog và thông báo kích hoạt bắt buộc.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN, email duy nhất, hồ sơ và chính sách mật khẩu; băm mật khẩu tạm theo auth hiện có. Tạo PENDING_VERIFICATION với emailVerifiedAt=null, requirePasswordReset=true và 0 thẻ. Đưa email kích hoạt bắt buộc vào hàng gửi, ghi audit; gửi email lỗi vẫn giữ tài khoản chờ.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Hộp thoại Tạo Người Dùng Mới (SCR-ADM-07):</p><ul><li>Left/Header: Tiêu đề hộp thoại &quot;Tạo Người Dùng Mới&quot; kèm biểu tượng thêm tài khoản.</li><li>Center: Họ tên, Email, mật khẩu tạm/tự sinh, System Role ADMIN/USER và chọn gói từ catalog subscription hiện có. Email kích hoạt và thay mật khẩu lần đầu là bắt buộc, không có checkbox bỏ qua.</li><li>Buttons: Nút &quot;Tạo tài khoản&quot; (màu xanh), Nút &quot;Hủy bỏ&quot;.</li><li>Footer: Tài khoản bắt đầu PENDING_VERIFICATION, 0 thẻ. Trước khi xác thực email và thay mật khẩu, chỉ được kích hoạt, đặt mật khẩu, đăng xuất và hỗ trợ.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: fullName (2–100 ký tự), email (đúng định dạng), role (ADMIN/USER); mật khẩu tạm nếu không tự sinh: ít nhất 8 ký tự, một chữ số và một ký tự đặc biệt.</li><li><strong>Input optional</strong>: phoneNumber, requestedPlanId từ catalog subscription; tạo tài khoản không tự cấp quyền gói trả phí khi chưa thanh toán.</li><li><strong>System data</strong>: adminId, createdAt, initialStatus=PENDING_VERIFICATION, emailVerifiedAt=null, requirePasswordReset=true, initialStrikes=0, trạng thái gửi email kích hoạt.</li><li><strong>Output</strong>: Thông tin người dùng mới tạo (id, email, fullName, role, status) kèm mã HTTP 201 Created.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-01</strong>: Email duy nhất toàn nền tảng, theo quy tắc chuẩn hóa hiện có.</li><li><strong>BR-02</strong>: Mật khẩu tạm/mới cần ít nhất 8 ký tự, một chữ số và một ký tự đặc biệt; băm BCrypt cost 12 theo FR gốc. Tái sử dụng kiểm tra/băm của auth và đối chiếu điểm khác trong plan kỹ thuật; không log mật khẩu hoặc token kích hoạt.</li><li><strong>BR-82</strong>: System role chỉ gồm ADMIN và USER. Quyền thành viên Agency/Workspace quản lý riêng. Mã gói lấy từ catalog subscription hiện có (hiện tại BASIC, PRO, ENTERPRISE), không tạo danh mục gói cứng khác.</li><li><strong>BR-63</strong>: Chỉ ADMIN tạo tài khoản. Email kích hoạt bắt buộc xác minh sở hữu email; tạo tài khoản chưa đánh dấu email đã xác thực.</li><li><strong>BR-15</strong>: Chưa đủ cả xác thực email và thay mật khẩu ban đầu thì chỉ cho kích hoạt/xác thực email, đặt mật khẩu, đăng xuất và hỗ trợ. Chặn dashboard, dữ liệu Agency, AI, đăng bài và thao tác thanh toán trên cả UI/API.</li><li><strong>BR-15</strong>: Hoàn tất thì đặt emailVerifiedAt, xóa requirePasswordReset và kích hoạt nếu không có xử phạt/xóa riêng. Xác thực email không cần Admin duyệt hoặc thiết lập lại 2FA.</li><li><strong>BR-60</strong>: Quyền gói trả phí theo luồng subscription/thanh toán hiện có; tạo tài khoản không phải sự kiện thanh toán, hóa đơn hoặc doanh thu.</li><li><strong>BR-16</strong>: Audit tạo/kích hoạt nhưng không lưu bí mật.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Người dùng không có quyền ADMIN → Display: MSG39</li><li>Để trống Họ tên hoặc Email → Display: MSG02</li><li>Email sai định dạng → Display: MSG04</li><li>Email đã tồn tại trong hệ thống → Display: MSG08</li><li>Mật khẩu tạm thời không đạt chuẩn bảo mật → Display: MSG05</li><li>Tạo tài khoản thành công → Display: MSG10</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin mở SCR-ADM-07, nhập hồ sơ, role ADMIN/USER và tùy chọn yêu cầu gói catalog.</li><li>Hệ thống kiểm tra duy nhất email và quy tắc auth/mật khẩu hiện có.</li><li>Tạo tài khoản chờ với 0 thẻ và bắt buộc cả hai điều kiện kích hoạt.</li><li>Xếp email kích hoạt vào hàng gửi, ghi audit và hiển thị trạng thái chờ gửi/kích hoạt.</li><li>User mở luồng kích hoạt, xác thực email và đặt mật khẩu riêng mới.</li><li>Đủ cả hai điều kiện thì kích hoạt tài khoản hợp lệ và mở quyền bình thường; gói trả phí vẫn theo quy tắc thanh toán.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Thiếu ADMIN → MSG39; thiếu trường/email sai/mật khẩu sai/email trùng → MSG02/04/05/08 hiện có.</li><li>4.a1: Email lỗi → giữ PENDING_VERIFICATION, hiển thị retry/gửi lại; không tạo tài khoản khác.</li><li>5.a1: Token kích hoạt hết hạn/đã dùng → theo chính sách gửi lại/xác thực hiện có; không mở quyền ứng dụng.</li><li>6.a1: Chỉ hoàn tất một điều kiện → vẫn hạn chế ở luồng kích hoạt; không bỏ qua xử phạt/xóa tài khoản.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Tài khoản mới giữ PENDING_VERIFICATION đến khi đủ điều kiện kích hoạt bắt buộc.</li><li>System role là ADMIN/USER; quyền Agency và quyền gói trả phí quản lý riêng.</li><li>Lưu tình trạng gửi email và audit; không log mật khẩu/token.</li></ul>",14)])])}const k=i(l,[["render",r]]);export{m as __pageData,k as default};
